public static boolean Exists(WMSPickingRouteID _routeId)
{
    MobConsolidatedPickingRouteOrders	routeOrders;
    select firstonly RecId,PickingRouteID from routeOrders where routeOrders.PickingRouteID == _routeId;
    return routeOrders.RecId;
}

public static MobConsolidatedPickingRouteId belongsTo(WMSPickingRouteID _routeId)
{
    MobConsolidatedPickingRouteOrders	routeOrders;
    select firstonly RecId,PickingRouteID,ConsolidatedPickingRouteId from routeOrders where routeOrders.PickingRouteID == _routeId;
    return routeOrders.ConsolidatedPickingRouteId;
}

public static Set getRouteSiblings(WMSPickingRouteID _routeId)
{
    Set routeSet = new Set(Types::String);
    MobConsolidatedPickingRouteId		consolidateID = MobConsolidatedPickingRouteOrders::belongsTo(_routeId);
    MobConsolidatedPickingRouteOrders	routeOrders;

    while select routeOrders where routeOrders.ConsolidatedPickingRouteId == consolidateID
    {
        routeSet.add(routeOrders.PickingRouteID);
    }
    routeSet.add(_routeId);
    return routeSet;
}

public static WMSPickingRouteID getFirstRouteChild(MobConsolidatedPickingRouteId		_consolidateID)
{
    MobConsolidatedPickingRouteOrders	routeOrders;
    select firstonly RecId,PickingRouteID,ConsolidatedPickingRouteId from routeOrders where routeOrders.ConsolidatedPickingRouteId == _consolidateID;
    return routeOrders.PickingRouteID;
}

	public static WMSPickingRouteID routeIdFromRecid(RefRecId _recId)
    {
        WMSOrderTrans           orderTrans;
        select firstonly routeId, RecId from orderTrans where orderTrans.RecId == _recId;
        return orderTrans.routeId;
    }
